import { NextResponse } from 'next/server'

export function generateImageMetadata() {
    return [
        { id: '192', size: { width: 192, height: 192 }, alt: 'App Icon' },
        { id: '512', size: { width: 512, height: 512 }, alt: 'App Icon' }
    ]
}

export default function Icon({ id }: { id: string }) {
    const ICON_DATA: Record<string, Buffer> = {
        '192': Buffer.from(
            '',
            'base64'
        ),
        '512': Buffer.from(
            '',
            'base64'
        ),
    }

    const iconBuffer = ICON_DATA[id]

    if (!iconBuffer) {
        return new NextResponse('Not found', { status: 404 })
    }

    return new NextResponse(new Uint8Array(iconBuffer), {
        headers: {
            'Content-Type': 'image/png',
            'Cache-Control': 'public, max-age=31536000, immutable',
        },
    })
}
